package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path"
	"path/filepath"
	"reflect"
	"slices"
	"strings"
	"time"
)

const bindingsHeader = "// Code generated by `bun run bindings` (apps/desktop/bindings.go). DO NOT EDIT.\n\n"

// rpcModule and modelsModule are the import paths the generated files use.
const (
	rpcModule    = "#lib/backend/rpc.ts"
	modelsModule = "#lib/backend/generated/models.ts"
)

var timeType = reflect.TypeFor[time.Time]()

// writeBindings writes App.ts (one function per exported App method) and
// models.ts (an interface per Go struct they use, grouped by package) into
// directory. Parameter names come from the Go source in the working directory.
func writeBindings(directory string) error {
	parameterNames, err := appParameterNames(".")
	if err != nil {
		return err
	}
	generator := newTypeScriptGenerator()
	client := generator.client(reflect.TypeFor[*App](), parameterNames)
	models := generator.models()

	err = os.MkdirAll(directory, 0o755)
	if err != nil {
		return fmt.Errorf("create %s: %w", directory, err)
	}
	err = os.WriteFile(filepath.Join(directory, "App.ts"), []byte(client), 0o644)
	if err != nil {
		return fmt.Errorf("write App.ts: %w", err)
	}
	err = os.WriteFile(filepath.Join(directory, "models.ts"), []byte(models), 0o644)
	if err != nil {
		return fmt.Errorf("write models.ts: %w", err)
	}
	return nil
}

// appParameterNames maps each method declared on *App to its parameter names,
// which reflection does not know.
func appParameterNames(directory string) (map[string][]string, error) {
	files, err := filepath.Glob(filepath.Join(directory, "*.go"))
	if err != nil {
		return nil, fmt.Errorf("list Go files: %w", err)
	}
	names := make(map[string][]string)
	fileSet := token.NewFileSet()
	for _, file := range files {
		parsed, err := parser.ParseFile(fileSet, file, nil, parser.SkipObjectResolution)
		if err != nil {
			return nil, fmt.Errorf("parse %s: %w", file, err)
		}
		collectAppMethods(parsed, names)
	}
	return names, nil
}

func collectAppMethods(file *ast.File, names map[string][]string) {
	for _, declaration := range file.Decls {
		function, isFunction := declaration.(*ast.FuncDecl)
		if !isFunction || !isAppReceiver(function.Recv) {
			continue
		}
		var parameters []string
		for _, field := range function.Type.Params.List {
			for _, name := range field.Names {
				parameters = append(parameters, name.Name)
			}
		}
		names[function.Name.Name] = parameters
	}
}

func isAppReceiver(receiver *ast.FieldList) bool {
	if receiver == nil || len(receiver.List) != 1 {
		return false
	}
	star, isPointer := receiver.List[0].Type.(*ast.StarExpr)
	if !isPointer {
		return false
	}
	identifier, isIdentifier := star.X.(*ast.Ident)
	return isIdentifier && identifier.Name == "App"
}

// typeScriptGenerator turns Go types into TypeScript, remembering every named
// struct it meets so models() can declare it.
type typeScriptGenerator struct {
	structs   map[reflect.Type]bool
	pending   []reflect.Type
	namespace map[string]bool
}

func newTypeScriptGenerator() *typeScriptGenerator {
	return &typeScriptGenerator{structs: make(map[reflect.Type]bool), namespace: make(map[string]bool)}
}

func (generator *typeScriptGenerator) client(target reflect.Type, parameterNames map[string][]string) string {
	var functions strings.Builder
	for index := range target.NumMethod() {
		method := target.Method(index)
		functions.WriteString(generator.function(method, parameterNames[method.Name]))
	}

	var output strings.Builder
	output.WriteString(bindingsHeader)
	fmt.Fprintf(&output, "import { call } from '%s';\n", rpcModule)
	namespaces := generator.usedNamespaces()
	if len(namespaces) > 0 {
		fmt.Fprintf(&output, "import type { %s } from '%s';\n", strings.Join(namespaces, ", "), modelsModule)
	}
	output.WriteString(functions.String())
	return output.String()
}

func (generator *typeScriptGenerator) function(method reflect.Method, names []string) string {
	parameterCount := method.Type.NumIn() - 1
	parameters := make([]string, parameterCount)
	arguments := make([]string, parameterCount)
	for index := range parameterCount {
		name := fmt.Sprintf("argument%d", index+1)
		if index < len(names) {
			name = names[index]
		}
		parameters[index] = name + ": " + generator.nullable(method.Type.In(index+1))
		arguments[index] = name
	}
	return fmt.Sprintf("\nexport function %s(%s): Promise<%s> {\n\treturn call('%s', [%s]);\n}\n",
		method.Name, strings.Join(parameters, ", "), generator.result(method.Type),
		method.Name, strings.Join(arguments, ", "))
}

// result is the TypeScript type a method resolves to: its first output unless
// that is the error.
func (generator *typeScriptGenerator) result(methodType reflect.Type) string {
	if methodType.NumOut() == 0 || methodType.Out(0) == errorType {
		return "void"
	}
	return generator.nullable(methodType.Out(0))
}

// nullable is the type of a value that may encode as null (a nil pointer).
func (generator *typeScriptGenerator) nullable(goType reflect.Type) string {
	if goType.Kind() == reflect.Pointer {
		return generator.typeOf(goType.Elem()) + " | null"
	}
	return generator.typeOf(goType)
}

func (generator *typeScriptGenerator) typeOf(goType reflect.Type) string {
	if goType == timeType {
		return "string"
	}
	switch goType.Kind() {
	case reflect.Bool:
		return "boolean"
	case reflect.String:
		return "string"
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
		reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64,
		reflect.Float32, reflect.Float64:
		return "number"
	case reflect.Pointer:
		return generator.typeOf(goType.Elem())
	case reflect.Slice, reflect.Array:
		return generator.listOf(goType)
	case reflect.Map:
		return fmt.Sprintf("Record<%s, %s>", generator.typeOf(goType.Key()), generator.typeOf(goType.Elem()))
	case reflect.Struct:
		return generator.structName(goType)
	default:
		return "any"
	}
}

func (generator *typeScriptGenerator) listOf(goType reflect.Type) string {
	if goType.Elem().Kind() == reflect.Uint8 {
		// encoding/json writes []byte as base64.
		return "string"
	}
	return generator.typeOf(goType.Elem()) + "[]"
}

func (generator *typeScriptGenerator) structName(goType reflect.Type) string {
	if goType.Name() == "" {
		return "any"
	}
	namespace := namespaceOf(goType)
	generator.namespace[namespace] = true
	if !generator.structs[goType] {
		generator.structs[goType] = true
		generator.pending = append(generator.pending, goType)
	}
	return namespace + "." + goType.Name()
}

// namespaceOf is the TypeScript namespace for goType: its Go package name, and
// "main" for this package (whose path is the module path under `go test`).
func namespaceOf(goType reflect.Type) string {
	if goType.PkgPath() == reflect.TypeFor[App]().PkgPath() {
		return "main"
	}
	return path.Base(goType.PkgPath())
}

func (generator *typeScriptGenerator) usedNamespaces() []string {
	namespaces := make([]string, 0, len(generator.namespace))
	for namespace := range generator.namespace {
		namespaces = append(namespaces, namespace)
	}
	slices.Sort(namespaces)
	return namespaces
}

// models declares every struct met so far, including the ones only reachable
// through other structs' fields.
func (generator *typeScriptGenerator) models() string {
	declarations := make(map[string][]string)
	for len(generator.pending) > 0 {
		goType := generator.pending[0]
		generator.pending = generator.pending[1:]
		namespace := namespaceOf(goType)
		declarations[namespace] = append(declarations[namespace], generator.interfaceOf(goType))
	}

	var output strings.Builder
	output.WriteString(bindingsHeader)
	for _, namespace := range generator.usedNamespaces() {
		interfaces := declarations[namespace]
		slices.Sort(interfaces)
		fmt.Fprintf(&output, "export namespace %s {\n%s}\n\n", namespace, strings.Join(interfaces, "\n"))
	}
	return strings.TrimSuffix(output.String(), "\n")
}

func (generator *typeScriptGenerator) interfaceOf(goType reflect.Type) string {
	var output strings.Builder
	fmt.Fprintf(&output, "\texport interface %s {\n", goType.Name())
	for _, field := range jsonFields(goType) {
		fmt.Fprintf(&output, "\t\t%s: %s;\n", field.declaredName(), generator.fieldType(field))
	}
	output.WriteString("\t}\n")
	return output.String()
}

func (generator *typeScriptGenerator) fieldType(field jsonField) string {
	if field.asString {
		return "string"
	}
	if field.optional {
		return generator.typeOf(field.goType)
	}
	return generator.nullable(field.goType)
}
